create or replace function public.admin_update_tournament_schedule(\n  p_tournament_id bigint,\n  p_tournament_date date,\n  p_scheduled_start_time time\n)\nreturns public.tournaments\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_row public.tournaments;\n  v_today date := (now() at time zone 'Asia/Dhaka')::date;\nbegin\n  if not exists (select 1 from public.profiles where id = auth.uid() and role = 'ADMIN') then\n    raise exception 'Admin access required';\n  end if;\n  if p_tournament_date < v_today + 1 then\n    raise exception 'Only future-day tournament schedules can be changed';\n  end if;\n  if extract(minute from p_scheduled_start_time) not in (0,30) or extract(second from p_scheduled_start_time) <> 0 then\n    raise exception 'Tournament time must be on a 30-minute slot';\n  end if;\n  select * into v_row from public.tournaments where id = p_tournament_id for update;\n  if not found then raise exception 'Tournament not found'; end if;\n  if v_row.status not in ('REGISTRATION','FULL') then raise exception 'Only upcoming tournaments can be rescheduled'; end if;\n  if exists (select 1 from public.tournaments t where t.id <> p_tournament_id and t.tournament_date = p_tournament_date and t.scheduled_start_time = p_scheduled_start_time) then\n    raise exception 'Another tournament already uses this date and time';\n  end if;\n  update public.tournaments set tournament_date=p_tournament_date, scheduled_start_time=p_scheduled_start_time where id=p_tournament_id returning * into v_row;\n  return v_row;\nend;\n$$;\n\nrevoke all on function public.admin_update_tournament_schedule(bigint,date,time) from public;\ngrant execute on function public.admin_update_tournament_schedule(bigint,date,time) to authenticated;\n